/**
 * Vizamigo - Pasaport & Vize Veri Tabanı
 * 199 ülke ve bölge için pasaport vize rejimleri, kural notları ve doğrulama durumları.
 */

export type VisaCategory = 'free' | 'id' | 'evisa' | 'voa' | 'eta' | 'visa' | 'none';

export interface CountryItem {
  c: string; // ISO 2 code
  v: string; // raw code from dataset (number of days, 'vf', 'e', 'voa', 'eta', 'v', 'x')
  cat: VisaCategory;
  id: boolean; // national ID card entry eligible
}

export interface DetailedInfo {
  n: string; // Açıklama
  u: string; // Resmi link
  h: string; // Site adı
  d: string; // Doğrulama tarihi
  nEn?: string; // English localized note
  nDe?: string; // German localized note
}

export interface DigitalNomadVisa {
  countryCode: string;
  countryName: string;
  visaName: string;
  incomeRequired: string;
  duration: string;
  taxInfo: string;
  processingTime: string;
  officialUrl: string;
  keyRequirements: string[];
}

export interface TransitRule {
  countryCode: string;
  countryName: string;
  ruleTitle: string;
  summary: string;
  conditions: string[];
  exceptions: string[];
  officialUrl?: string;
  // Localization properties
  ruleTitleEn?: string;
  summaryEn?: string;
  conditionsEn?: string[];
  exceptionsEn?: string[];
}

export interface EmergencyInfo {
  countryCode: string;
  police: string;
  ambulance: string;
  general: string;
  consulateNote: string;
}

